+  @Test
+  public void testResultLevelCacheWithMultiplePostAggregators() throws IOException
+  {
+    final ObjectMapper objectMapper = TestHelper.makeJsonMapper();
+    final List<PostAggregator> postAggregators = ImmutableList.of(
+        new ExpressionPostAggregator("a2", "rows * 2", null, null, TestExprMacroTable.INSTANCE),
+        new ExpressionPostAggregator("a3", "rows * 3", null, null, TestExprMacroTable.INSTANCE)
+    );
+
+    for (Granularity granularity : ImmutableList.of(Granularities.ALL, Granularities.DAY)) {
+      for (int postAggregatorCount = 0; postAggregatorCount <= postAggregators.size(); postAggregatorCount++) {
+        final GroupByQuery query = GroupByQuery.builder()
+            .setDataSource(QueryRunnerTestHelper.DATA_SOURCE)
+            .setQuerySegmentSpec(QueryRunnerTestHelper.FIRST_TO_THIRD)
+            .setDimensions(
+                new DefaultDimensionSpec("channel", "channel"),
+                new DefaultDimensionSpec("cityName", "cityName")
+            )
+            .setAggregatorSpecs(QueryRunnerTestHelper.ROWS_COUNT)
+            .setPostAggregatorSpecs(postAggregators.subList(0, postAggregatorCount))
+            .setGranularity(granularity)
+            .build();
+
+        final ResultRow result = ResultRow.create(query.getResultRowSizeWithPostAggregators());
+        if (query.getResultRowHasTimestamp()) {
+          result.set(0, 123L);
+        }
+        result.set(query.getResultRowDimensionStart(), "#en.wikipedia");
+        result.set(query.getResultRowDimensionStart() + 1, null);
+        result.set(query.getResultRowAggregatorStart(), 10516);
+        for (int i = 0; i < postAggregatorCount; i++) {
+          result.set(query.getResultRowPostAggregatorStart() + i, 10516 * (i + 2));
+        }
+
+        final CacheStrategy<ResultRow, Object, GroupByQuery> strategy =
+            new GroupByQueryQueryToolChest(null).getCacheStrategy(query);
+        final Object preparedValue = strategy.prepareForCache(true).apply(result);
+        final Object fromCacheValue = objectMapper.readValue(
+            objectMapper.writeValueAsBytes(preparedValue),
+            strategy.getCacheObjectClazz()
+        );
+
+        Assert.assertEquals(
+            result,
+            strategy.pullFromCache(true).apply(fromCacheValue)
+        );
+      }
+    }
+  }
+
